 87→// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
 88→func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
 89→	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
 90→	if err != nil {
 91→		return fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
 92→	}
 93→
 94→	blobHash, err := CreateBlobFromContent(s.repo, data)
 95→	if err != nil {
 96→		return fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
 97→	}
 98→
 99→	entries[paths.GenerationFileName] = object.TreeEntry{
100→		Name: paths.GenerationFileName,
101→		Mode: filemode.Regular,
102→		Hash: blobHash,
103→	}
104→
105→	return nil
106→}
