108→// updateGenerationForWrite reads the current generation metadata, appends the
109→// checkpoint ID (if not already present), and updates timestamps.
110→// Returns the updated metadata for the caller to write into the tree.
111→func (s *V2GitStore) updateGenerationForWrite(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, now time.Time) (GenerationMetadata, error) {
112→	gen, err := s.readGeneration(rootTreeHash)
113→	if err != nil {
114→		return GenerationMetadata{}, err
115→	}
116→
117→	cpStr := checkpointID.String()
118→
119→	// Only append if checkpoint ID is not already present (multi-session writes
120→	// to the same checkpoint should not duplicate the ID).
121→	found := false
122→	for _, existing := range gen.Checkpoints {
123→		if existing == cpStr {
124→			found = true
125→			break
126→		}
127→	}
128→	if !found {
129→		gen.Checkpoints = append(gen.Checkpoints, cpStr)
130→	}
131→
132→	gen.NewestCheckpointAt = now
133→	if gen.OldestCheckpointAt.IsZero() {
134→		gen.OldestCheckpointAt = now
135→	}
136→
137→	return gen, nil
138→}
