140→// addGenerationToRootTree adds generation.json to an existing root tree, returning
141→// a new root tree hash. Preserves all existing entries (shard directories, etc.).
142→func (s *V2GitStore) addGenerationToRootTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
143→	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
144→	if err != nil {
145→		return plumbing.ZeroHash, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
146→	}
147→
148→	blobHash, err := CreateBlobFromContent(s.repo, data)
149→	if err != nil {
150→		return plumbing.ZeroHash, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
151→	}
152→
153→	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{
154→		{Name: paths.GenerationFileName, Mode: filemode.Regular, Hash: blobHash},
155→	}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
156→}
