158→// generationRefWidth is the zero-padded width of archived generation ref names.
159→const generationRefWidth = 13
160→
161→// listArchivedGenerations returns the names of all archived generation refs
162→// (everything under V2FullRefPrefix except "current"), sorted ascending.
163→func (s *V2GitStore) listArchivedGenerations() ([]string, error) {
164→	refs, err := s.repo.References()
165→	if err != nil {
166→		return nil, fmt.Errorf("failed to list references: %w", err)
167→	}
168→
169→	var archived []string
170→	err = refs.ForEach(func(ref *plumbing.Reference) error {
171→		name := ref.Name().String()
172→		if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
173→			return nil
174→		}
175→		suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
176→		if suffix == "current" {
177→			return nil
178→		}
179→		archived = append(archived, suffix)
180→		return nil
181→	})
182→	if err != nil {
183→		return nil, fmt.Errorf("failed to iterate references: %w", err)
184→	}
185→
186→	sort.Strings(archived)
187→	return archived, nil
188→}
189→
190→// nextGenerationNumber returns the next sequential generation number for archiving.
191→// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
192→func (s *V2GitStore) nextGenerationNumber() (int, error) {
193→	archived, err := s.listArchivedGenerations()
194→	if err != nil {
195→		return 0, err
196→	}
197→	if len(archived) == 0 {
198→		return 1, nil
199→	}
200→
201→	// Parse the highest archive number
202→	highest := archived[len(archived)-1]
203→	n, err := strconv.Atoi(strings.TrimLeft(highest, "0"))
204→	if err != nil {
205→		return 0, fmt.Errorf("failed to parse archived generation number %q: %w", highest, err)
206→	}
207→	return n + 1, nil
208→}
209→
210→// rotateGeneration archives the current /full/current generation and creates
211→// a fresh orphan. This is a 3-phase operation:
212→//
213→//  1. Archive: determine the next generation number, create a new ref pointing
214→//     to the current /full/current commit.
215→//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
216→//     point /full/current at it.
217→func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
218→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
219→
220→	currentRef, err := s.repo.Reference(refName, true)
221→	if err != nil {
222→		return fmt.Errorf("rotation: failed to read /full/current: %w", err)
223→	}
224→
225→	archiveNumber, err := s.nextGenerationNumber()
226→	if err != nil {
227→		return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
228→	}
229→
230→	// Phase 1: Archive — create ref pointing to the current commit
231→	archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
232→	archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
233→	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
234→		return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
235→	}
236→
237→	// Phase 2: Create fresh orphan /full/current
238→	seedGen := GenerationMetadata{
239→		Checkpoints: []string{},
240→	}
241→	seedEntries := make(map[string]object.TreeEntry)
242→	if err := s.writeGeneration(seedGen, seedEntries); err != nil {
243→		return fmt.Errorf("rotation: failed to build seed generation: %w", err)
244→	}
245→	seedTreeHash, err := BuildTreeFromEntries(s.repo, seedEntries)
246→	if err != nil {
247→		return fmt.Errorf("rotation: failed to build seed tree: %w", err)
248→	}
249→
250→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
251→	orphanCommitHash, err := CreateCommit(s.repo, seedTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
252→	if err != nil {
253→		return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
254→	}
255→
256→	orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
257→	if err := s.repo.Storer.SetReference(orphanRef); err != nil {
258→		return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
259→	}
260→
261→	logging.Info(ctx, "generation rotation complete",
262→		slog.Int("archived_generation", archiveNumber),
263→		slog.String("archive_ref", string(archiveRefName)),
264→	)
265→
266→	return nil
267→}
