371→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
372→// Transcripts accumulate across checkpoints — each write splices into the existing
373→// tree. Generation metadata (generation.json) at the tree root is updated on every
374→// write with the new checkpoint ID and timestamps.
375→//
376→// sessionIndex is the session slot (0-based), determined by the caller to stay
377→// consistent with the /main ref's session numbering.
378→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
379→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
380→	transcript := opts.Transcript
381→	if len(transcript) == 0 && opts.TranscriptPath != "" {
382→		var readErr error
383→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
384→		if readErr != nil {
385→			transcript = nil
386→		}
387→	}
388→	if len(transcript) == 0 {
389→		return nil // No transcript to write
390→	}
391→
392→	if err := validateWriteOpts(opts); err != nil {
393→		return err
394→	}
395→
396→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
397→	if err := s.ensureRef(refName); err != nil {
398→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
399→	}
400→
401→	parentHash, rootTreeHash, err := s.getRefState(refName)
402→	if err != nil {
403→		return err
404→	}
405→
406→	basePath := opts.CheckpointID.Path() + "/"
407→	checkpointPath := opts.CheckpointID.Path()
408→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
409→
410→	// Read existing entries at this checkpoint's shard path (accumulate, don't replace)
411→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
412→	if err != nil {
413→		return err
414→	}
415→
416→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
417→	if err != nil {
418→		return err
419→	}
420→
421→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
422→		return err
423→	}
424→
425→	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
426→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
427→	if err != nil {
428→		return err
429→	}
430→
431→	// Update generation.json at the tree root with the new checkpoint ID and timestamps.
432→	// This reads from the pre-splice root tree (to get existing metadata) and writes
433→	// into the post-splice tree (which already has the shard directories).
434→	gen, err := s.updateGenerationForWrite(rootTreeHash, opts.CheckpointID, time.Now().UTC())
435→	if err != nil {
436→		return fmt.Errorf("failed to update generation metadata: %w", err)
437→	}
438→	newTreeHash, err = s.addGenerationToRootTree(newTreeHash, gen)
439→	if err != nil {
440→		return fmt.Errorf("failed to add generation.json to tree: %w", err)
441→	}
442→
443→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
444→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
445→		return err
446→	}
447→
448→	// Check if rotation is needed after successful write.
449→	if len(gen.Checkpoints) >= s.maxCheckpoints() {
450→		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
451→			logging.Warn(ctx, "generation rotation failed",
452→				slog.String("error", rotErr.Error()),
453→				slog.Int("checkpoint_count", len(gen.Checkpoints)),
454→			)
455→			// Non-fatal: rotation failure doesn't invalidate the write
456→		}
457→	}
458→
459→	return nil
460→}
461→
462→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
463→// Returns the redacted transcript bytes so the caller can compute the content hash.
464→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
465→	// Redact secrets before chunking
466→	redacted, err := redact.JSONLBytes(transcript)
467→	if err != nil {
468→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
469→	}
470→
471→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
472→	if err != nil {
473→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
474→	}
475→
476→	for i, chunk := range chunks {
477→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
478→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
479→		if err != nil {
480→			return nil, err
481→		}
482→		entries[chunkPath] = object.TreeEntry{
483→			Name: chunkPath,
484→			Mode: filemode.Regular,
485→			Hash: blobHash,
486→		}
487→	}
488→
489→	return redacted, nil
490→}
491→
492→// validateWriteOpts validates identifiers in WriteCommittedOptions.
493→func validateWriteOpts(opts WriteCommittedOptions) error {
494→	if opts.CheckpointID.IsEmpty() {
495→		return errors.New("invalid checkpoint options: checkpoint ID is required")
496→	}
497→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
498→		return fmt.Errorf("invalid checkpoint options: %w", err)
499→	}
500→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
501→		return fmt.Errorf("invalid checkpoint options: %w", err)
502→	}
503→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
504→		return fmt.Errorf("invalid checkpoint options: %w", err)
505→	}
506→	return nil
507→}
