 13→	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
 14→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 15→	"github.com/entireio/cli/cmd/entire/cli/logging"
 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→	"github.com/go-git/go-git/v6/plumbing"
 18→	"github.com/go-git/go-git/v6/plumbing/filemode"
 19→	"github.com/go-git/go-git/v6/plumbing/object"
 20→)
 21→
 22→// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
 23→// When a generation reaches this many checkpoints, it is archived
 24→// and a fresh /full/current is created.
 25→const DefaultMaxCheckpointsPerGeneration = 100
 26→
 27→// GenerationMetadata tracks the state of a /full/* generation.
 28→// Stored at the tree root as generation.json and updated on every WriteCommitted.
 29→// UpdateCommitted (stop-time finalization) does NOT update this file since it
 30→// replaces an existing transcript rather than adding a new checkpoint.
 31→//
 32→// The generation's sequence number is derived from the ref name (e.g.,
 33→// refs/entire/checkpoints/v2/full/0000000000001 → generation 1), not stored
 34→// in this struct. The checkpoint count is len(Checkpoints).
 35→type GenerationMetadata struct {
 36→	// Checkpoints is the list of checkpoint IDs stored in this generation.
 37→	// Used for finding which generation holds a specific checkpoint
 38→	// without walking the tree. len(Checkpoints) gives the count.
 39→	Checkpoints []id.CheckpointID `json:"checkpoints"`
 40→
 41→	// OldestCheckpointAt is the creation time of the earliest checkpoint.
 42→	OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`
 43→
 44→	// NewestCheckpointAt is the creation time of the most recent checkpoint.
 45→	NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
 46→}
 47→
 48→// readGeneration reads generation.json from the given tree hash.
 49→// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
 50→func (s *V2GitStore) readGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
 51→	if treeHash == plumbing.ZeroHash {
 52→		return GenerationMetadata{}, nil
 53→	}
 54→
 55→	tree, err := s.repo.TreeObject(treeHash)
 56→	if err != nil {
 57→		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
 58→	}
 59→
 60→	file, err := tree.File(paths.GenerationFileName)
 61→	if err != nil {
 62→		return GenerationMetadata{}, nil //nolint:nilerr // Missing file means empty/new generation
 63→	}
 64→
 65→	content, err := file.Contents()
 66→	if err != nil {
 67→		return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
 68→	}
 69→
 70→	var gen GenerationMetadata
 71→	if err := json.Unmarshal([]byte(content), &gen); err != nil {
 72→		return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
 73→	}
 74→
 75→	return gen, nil
 76→}
 77→
 78→// readGenerationFromRef reads generation.json from the tree pointed to by the given ref.
 79→func (s *V2GitStore) readGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
 80→	_, treeHash, err := s.getRefState(refName)
 81→	if err != nil {
 82→		return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
 83→	}
 84→	return s.readGeneration(treeHash)
 85→}
 86→
 87→// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
 88→// Returns a TreeEntry ready to be placed in a tree.
 89→func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
 90→	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
 91→	if err != nil {
 92→		return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
 93→	}
 94→
 95→	blobHash, err := CreateBlobFromContent(s.repo, data)
 96→	if err != nil {
 97→		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
 98→	}
 99→
100→	return object.TreeEntry{
101→		Name: paths.GenerationFileName,
102→		Mode: filemode.Regular,
103→		Hash: blobHash,
104→	}, nil
105→}
106→
107→// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
108→func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
109→	entry, err := s.marshalGenerationBlob(gen)
110→	if err != nil {
111→		return err
112→	}
113→	entries[paths.GenerationFileName] = entry
114→	return nil
115→}
116→
117→// updateGenerationForWrite reads the current generation metadata, appends the
118→// checkpoint ID (if not already present), and updates timestamps.
119→// Returns the updated metadata for the caller to write into the tree.
120→func (s *V2GitStore) updateGenerationForWrite(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, now time.Time) (GenerationMetadata, error) {
121→	gen, err := s.readGeneration(rootTreeHash)
122→	if err != nil {
123→		return GenerationMetadata{}, err
124→	}
125→
126→	// Only append if checkpoint ID is not already present (multi-session writes
127→	// to the same checkpoint should not duplicate the ID).
128→	found := false
129→	for _, existing := range gen.Checkpoints {
130→		if existing == checkpointID {
131→			found = true
132→			break
133→		}
134→	}
135→	if !found {
136→		gen.Checkpoints = append(gen.Checkpoints, checkpointID)
137→	}
138→
139→	gen.NewestCheckpointAt = now
140→	if gen.OldestCheckpointAt.IsZero() {
141→		gen.OldestCheckpointAt = now
142→	}
143→
144→	return gen, nil
145→}
146→
147→// addGenerationToRootTree adds generation.json to an existing root tree, returning
148→// a new root tree hash. Preserves all existing entries (shard directories, etc.).
149→func (s *V2GitStore) addGenerationToRootTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
150→	entry, err := s.marshalGenerationBlob(gen)
151→	if err != nil {
152→		return plumbing.ZeroHash, err
153→	}
154→
155→	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
156→		UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
157→}
158→
159→// generationRefWidth is the zero-padded width of archived generation ref names.
160→const generationRefWidth = 13
161→
162→// listArchivedGenerations returns the names of all archived generation refs
163→// (everything under V2FullRefPrefix except "current"), sorted ascending.
164→func (s *V2GitStore) listArchivedGenerations() ([]string, error) {
165→	refs, err := s.repo.References()
166→	if err != nil {
167→		return nil, fmt.Errorf("failed to list references: %w", err)
168→	}
169→
170→	var archived []string
171→	err = refs.ForEach(func(ref *plumbing.Reference) error {
172→		name := ref.Name().String()
173→		if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
174→			return nil
175→		}
176→		suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
177→		if suffix == "current" {
178→			return nil
179→		}
180→		archived = append(archived, suffix)
181→		return nil
182→	})
183→	if err != nil {
184→		return nil, fmt.Errorf("failed to iterate references: %w", err)
185→	}
186→
187→	sort.Strings(archived)
188→	return archived, nil
189→}
190→
191→// nextGenerationNumber returns the next sequential generation number for archiving.
192→// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
193→func (s *V2GitStore) nextGenerationNumber() (int, error) {
194→	archived, err := s.listArchivedGenerations()
195→	if err != nil {
196→		return 0, err
197→	}
198→	if len(archived) == 0 {
199→		return 1, nil
200→	}
201→
202→	highest := archived[len(archived)-1]
203→	n, err := strconv.ParseInt(highest, 10, 64)
204→	if err != nil {
205→		return 0, fmt.Errorf("failed to parse archived generation number %q: %w", highest, err)
206→	}
207→	return int(n) + 1, nil
208→}
209→
210→// rotateGeneration archives the current /full/current generation and creates
211→// a fresh orphan. This is a 2-phase operation:
212→//
213→//  1. Archive: determine the next generation number, create a new ref pointing
214→//     to the current /full/current commit.
215→//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
216→//     point /full/current at it.
217→func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
218→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
219→
220→	currentRef, err := s.repo.Reference(refName, true)
221→	if err != nil {
222→		return fmt.Errorf("rotation: failed to read /full/current: %w", err)
223→	}
224→
225→	archiveNumber, err := s.nextGenerationNumber()
226→	if err != nil {
227→		return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
228→	}
229→
230→	// Phase 1: Archive — create ref pointing to the current commit
231→	archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
232→	archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
233→	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
234→		return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
235→	}
236→
237→	// Phase 2: Create fresh orphan /full/current
238→	seedGen := GenerationMetadata{
239→		Checkpoints: []id.CheckpointID{},
240→	}
241→	seedEntries := make(map[string]object.TreeEntry)
242→	if err := s.writeGeneration(seedGen, seedEntries); err != nil {
243→		return fmt.Errorf("rotation: failed to build seed generation: %w", err)
244→	}
245→	seedTreeHash, err := BuildTreeFromEntries(s.repo, seedEntries)
246→	if err != nil {
247→		return fmt.Errorf("rotation: failed to build seed tree: %w", err)
248→	}
249→
250→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
251→	orphanCommitHash, err := CreateCommit(s.repo, seedTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
252→	if err != nil {
253→		return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
254→	}
255→
256→	orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
257→	if err := s.repo.Storer.SetReference(orphanRef); err != nil {
258→		return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
259→	}
260→
261→	logging.Info(ctx, "generation rotation complete",
262→		slog.Int("archived_generation", archiveNumber),
263→		slog.String("archive_ref", string(archiveRefName)),
264→	)
265→
266→	return nil
267→}
