370→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
371→// Transcripts accumulate across checkpoints — each write splices into the existing
372→// tree. Generation metadata (generation.json) at the tree root is updated on every
373→// write with the new checkpoint ID and timestamps.
374→//
375→// sessionIndex is the session slot (0-based), determined by the caller to stay
376→// consistent with the /main ref's session numbering.
377→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
378→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
379→	transcript := opts.Transcript
380→	if len(transcript) == 0 && opts.TranscriptPath != "" {
381→		var readErr error
382→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
383→		if readErr != nil {
384→			transcript = nil
385→		}
386→	}
387→	if len(transcript) == 0 {
388→		return nil // No transcript to write
389→	}
390→
391→	if err := validateWriteOpts(opts); err != nil {
392→		return err
393→	}
394→
395→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
396→	if err := s.ensureRef(refName); err != nil {
397→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
398→	}
399→
400→	parentHash, rootTreeHash, err := s.getRefState(refName)
401→	if err != nil {
402→		return err
403→	}
404→
405→	basePath := opts.CheckpointID.Path() + "/"
406→	checkpointPath := opts.CheckpointID.Path()
407→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
408→
409→	// Read existing entries at this checkpoint's shard path (accumulate, don't replace)
410→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
411→	if err != nil {
412→		return err
413→	}
414→
415→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
416→	if err != nil {
417→		return err
418→	}
419→
420→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
421→		return err
422→	}
423→
424→	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
425→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
426→	if err != nil {
427→		return err
428→	}
429→
430→	// Update generation.json at the tree root with the new checkpoint ID and timestamps.
431→	// This reads from the pre-splice root tree (to get existing metadata) and writes
432→	// into the post-splice tree (which already has the shard directories).
433→	gen, err := s.updateGenerationForWrite(rootTreeHash, opts.CheckpointID, time.Now().UTC())
434→	if err != nil {
435→		return fmt.Errorf("failed to update generation metadata: %w", err)
436→	}
437→	newTreeHash, err = s.addGenerationToRootTree(newTreeHash, gen)
438→	if err != nil {
439→		return fmt.Errorf("failed to add generation.json to tree: %w", err)
440→	}
441→
442→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
443→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
444→		return err
445→	}
446→
447→	// Check if rotation is needed after successful write.
448→	if len(gen.Checkpoints) >= s.maxCheckpoints() {
449→		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
450→			logging.Warn(ctx, "generation rotation failed",
451→				slog.String("error", rotErr.Error()),
452→				slog.Int("checkpoint_count", len(gen.Checkpoints)),
453→			)
454→			// Non-fatal: rotation failure doesn't invalidate the write
455→		}
456→	}
457→
458→	return nil
459→}
