461→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
462→// Returns the redacted transcript bytes so the caller can compute the content hash.
463→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
464→	// Redact secrets before chunking
465→	redacted, err := redact.JSONLBytes(transcript)
466→	if err != nil {
467→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
468→	}
469→
470→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
471→	if err != nil {
472→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
473→	}
474→
475→	for i, chunk := range chunks {
476→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
477→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
478→		if err != nil {
479→			return nil, err
480→		}
481→		entries[chunkPath] = object.TreeEntry{
482→			Name: chunkPath,
483→			Mode: filemode.Regular,
484→			Hash: blobHash,
485→		}
486→	}
487→
488→	return redacted, nil
489→}
490→
491→// validateWriteOpts validates identifiers in WriteCommittedOptions.
492→func validateWriteOpts(opts WriteCommittedOptions) error {
493→	if opts.CheckpointID.IsEmpty() {
494→		return errors.New("invalid checkpoint options: checkpoint ID is required")
495→	}
496→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
497→		return fmt.Errorf("invalid checkpoint options: %w", err)
498→	}
499→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
500→		return fmt.Errorf("invalid checkpoint options: %w", err)
501→	}
502→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
503→		return fmt.Errorf("invalid checkpoint options: %w", err)
504→	}
505→	return nil
506→}
